n = 30
target_edges = 42

best_edges = []
best_adj = None

for attempt in range(2000):
    adj = [set() for _ in range(n)]
    edges = []

    all_possible = [(u, v) for u in range(n) for v in range(u+1, n)]
    random.shuffle(all_possible)

    for u, v in all_possible:
        if len(edges) >= target_edges:
            break
        if not has_short_cycle(adj, u, v, max_len=6):
            adj[u].add(v)
            adj[v].add(u)
            edges.append((u, v))

    if len(edges) >= target_edges:
        best_edges = edges
        best_adj = adj
        break

    if len(edges) > len(best_edges):
        best_edges = edges[:]
        best_adj = [s.copy() for s in adj]

print(f"Best: {len(best_edges)} edges")

if len(best_edges) >= target_edges:
    girth = find_girth(best_adj, n)
    print(f"Girth: {girth}")

    colors = greedy_color(best_adj, n)
    num_colors = max(colors) + 1
    print(f"Greedy coloring uses {num_colors} colors")

    valid = all(colors[u] != colors[v] for u, v in best_edges)
    print(f"Coloring valid: {valid}")

    print(f"\nEdges:")
    for e in sorted(best_edges):
        print(e)
